def bi(x, y): return min(range(len(B)), key=lambda i: (B[i][0]-x)**2 + (B[i][1]-y)**2)
def bsec(a, b):
    """國界上從頂點 a 逆時針走到頂點 b（含兩端）"""
    i, j, out = bi(*a), bi(*b), []
    while True:
        out.append(B[i][:2]);
        if i == j: break
        i = (i + 1) % len(B)
    return out
def ring(front, end, start): return [list(p) for p in front] + bsec(end, start)

