# ---------- 部隊 ----------
U, POS, ASG = [], [], []
def unit(id, side, name, orig, ech, br, label, parent, cmd, track, src, tier=None, note=None):
    u = dict(id=id, side=side, name_zh=name, name_orig=orig, echelon=ech, branch=br, parent_id=parent, label=label, display='both', domain='ground', source=WP + src, confidence='low')
    if tier is not None: u['tier'] = tier
    if note: u['note_zh'] = note
    U.append(u)
    if cmd:
        zh, og, title, how = cmd
        ASG.append(dict(unit_id=id, role='commander', name_zh=zh, name_orig=og, title_zh=title, **{'from': None, 'to': None},
                        source=(WP + src) if how == 'wp' else None, confidence='low', status_zh='維基百科，需查證' if how == 'wp' else '未對到條目，需查證'))
    assert len(track) == len(K), id
    for md, t in zip(K, track):
        if t is None: continue
        place, st = t; x, y = P(place)
        POS.append(dict(unit_id=id, date=Y + md, lng=round(x, 3), lat=round(y, 3), state=st, status='approx', precision_m=30000,
                        place_zh=place if isinstance(place, str) else None, source='narrative:' + src))
