def dump(path, obj):
    s = json.dumps(obj, ensure_ascii=False, indent=1)
    s = re.sub(r'\[\s+(-?[\d.]+),\s+(-?[\d.]+)(?:,\s+("[a-z]+"))?\s+\]', lambda m: '[' + ', '.join(x for x in m.groups() if x) + ']', s)
    open(path, 'w').write(s + '\n')
